create table xxventuri.xxeba_sales_attendance_t (
    att_id              number,
    employee_id         number,
    employee_name       varchar2(100 byte),
    attend_date         timestamp(6),
    attend_intime       timestamp(6),
    attend_in_lat       varchar2(100 byte),
    attend_in_long      varchar2(100 byte),
    attend_out_time     timestamp(6),
    attend_out_lat      varchar2(100 byte),
    attend_out_long     varchar2(100 byte),
    client_ip_address   varchar2(100 byte),
    device_id           varchar2(100 byte),
    source_app          char(1 byte),
    created_by          varchar2(200 byte),
    created_date        timestamp(6),
    updated_by          varchar2(100 byte),
    updated_date        timestamp(6),
    location_update     char(1 byte),
    attend_in_location  varchar2(1000 byte),
    attend_out_location varchar2(1000 byte)
);

alter table xxventuri.xxeba_sales_attendance_t
    add constraint att_id_pk primary key ( att_id )
        using index enable;


